/* Generación de un ODT relleno a partir de plantilla_examen.odt */
(function (global) {
  'use strict';

  const TEMPLATE_BASE64 = '';

  const ExamBuilder = (global.ExamBuilder = global.ExamBuilder || {});
  const Util = ExamBuilder.Util;

  const TYPE_LABELS = {
    multichoice: 'Opción múltiple',
    truefalse: 'Verdadero / Falso',
    shortanswer: 'Respuesta corta',
    essay: 'Ensayo',
    matching: 'Emparejamiento',
  };

  function escapeXml(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  function crc32(data) {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i += 1) {
      crc ^= data[i];
      for (let k = 0; k < 8; k += 1) {
        crc = (crc & 1) ? ((crc >>> 1) ^ 0xEDB88320) : (crc >>> 1);
      }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
  }

  function concatUint8Arrays(chunks) {
    let total = 0;
    chunks.forEach(function (chunk) { total += chunk.length; });
    const out = new Uint8Array(total);
    let offset = 0;
    chunks.forEach(function (chunk) {
      out.set(chunk, offset);
      offset += chunk.length;
    });
    return out;
  }

  async function inflateRaw(data) {
    if (typeof DecompressionStream === 'undefined') {
      throw new Error('El navegador no soporta DecompressionStream.');
    }
    const ds = new DecompressionStream('deflate-raw');
    const writer = ds.writable.getWriter();
    writer.write(data);
    writer.close();
    const reader = ds.readable.getReader();
    const chunks = [];
    while (true) {
      const result = await reader.read();
      if (result.done) break;
      chunks.push(result.value);
    }
    return concatUint8Arrays(chunks);
  }

  async function readZip(buffer) {
    const bytes = new Uint8Array(buffer);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);

    // Localizar EOCD
    let eocdOffset = -1;
    for (let i = bytes.length - 22; i >= 0; i -= 1) {
      if (bytes[i] === 0x50 && bytes[i + 1] === 0x4b && bytes[i + 2] === 0x05 && bytes[i + 3] === 0x06) {
        eocdOffset = i;
        break;
      }
    }
    if (eocdOffset < 0) throw new Error('No se encontró el final del archivo ZIP.');

    const cdOffset = view.getUint32(eocdOffset + 16, true);
    const cdSize = view.getUint32(eocdOffset + 12, true);

    const entries = [];
    let pos = cdOffset;
    const cdEnd = cdOffset + cdSize;
    while (pos < cdEnd) {
      if (view.getUint32(pos, true) !== 0x02014b50) break;
      const method = view.getUint16(pos + 10, true);
      const csize = view.getUint32(pos + 20, true);
      const usize = view.getUint32(pos + 24, true);
      const nameLen = view.getUint16(pos + 28, true);
      const extraLen = view.getUint16(pos + 30, true);
      const commentLen = view.getUint16(pos + 32, true);
      const localOffset = view.getUint32(pos + 42, true);

      const nameBytes = bytes.slice(pos + 46, pos + 46 + nameLen);
      const name = new TextDecoder('utf-8').decode(nameBytes);

      const localNameLen = view.getUint16(localOffset + 26, true);
      const localExtraLen = view.getUint16(localOffset + 28, true);
      const dataStart = localOffset + 30 + localNameLen + localExtraLen;
      const compressed = bytes.slice(dataStart, dataStart + csize);

      let data;
      if (method === 0) {
        data = compressed.slice();
      } else if (method === 8) {
        data = await inflateRaw(compressed);
      } else {
        throw new Error('Método de compresión no soportado (' + method + ') para ' + name);
      }

      entries.push({ name: name, data: data });
      pos += 46 + nameLen + extraLen + commentLen;
    }
    return entries;
  }

  function writeZip(entries) {
    const encoder = new TextEncoder();
    const localChunks = [];
    const centralChunks = [];
    let offset = 0;
    const centralMeta = [];

    entries.forEach(function (entry) {
      const nameBytes = encoder.encode(entry.name);
      const data = entry.data;
      const crc = crc32(data);
      const now = new Date();
      const dosTime = ((now.getHours() << 11) | (now.getMinutes() << 5) | (now.getSeconds() >> 1)) >>> 0;
      const dosDate = (((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate()) >>> 0;

      const localHeader = new Uint8Array(30 + nameBytes.length);
      const lh = new DataView(localHeader.buffer);
      lh.setUint32(0, 0x04034b50, true);
      lh.setUint16(4, 20, true);
      lh.setUint16(6, 0, true);
      lh.setUint16(8, 0, true); // store
      lh.setUint16(10, dosTime & 0xffff, true);
      lh.setUint16(12, dosDate & 0xffff, true);
      lh.setUint32(14, crc, true);
      lh.setUint32(18, data.length, true);
      lh.setUint32(22, data.length, true);
      lh.setUint16(26, nameBytes.length, true);
      lh.setUint16(28, 0, true);
      localHeader.set(nameBytes, 30);

      centralMeta.push({ nameBytes: nameBytes, crc: crc, size: data.length, offset: offset, dosTime: dosTime, dosDate: dosDate });
      localChunks.push(localHeader);
      localChunks.push(data);
      offset += localHeader.length + data.length;
    });

    const cdStart = offset;
    centralMeta.forEach(function (meta) {
      const header = new Uint8Array(46 + meta.nameBytes.length);
      const ch = new DataView(header.buffer);
      ch.setUint32(0, 0x02014b50, true);
      ch.setUint16(4, 20, true);
      ch.setUint16(6, 20, true);
      ch.setUint16(8, 0, true);
      ch.setUint16(10, 0, true);
      ch.setUint16(12, meta.dosTime & 0xffff, true);
      ch.setUint16(14, meta.dosDate & 0xffff, true);
      ch.setUint32(16, meta.crc, true);
      ch.setUint32(20, meta.size, true);
      ch.setUint32(24, meta.size, true);
      ch.setUint16(28, meta.nameBytes.length, true);
      ch.setUint16(30, 0, true);
      ch.setUint16(32, 0, true);
      ch.setUint16(34, 0, true);
      ch.setUint16(36, 0, true);
      ch.setUint32(38, 0, true);
      ch.setUint32(42, meta.offset, true);
      header.set(meta.nameBytes, 46);
      centralChunks.push(header);
      offset += header.length;
    });
    const cdSize = offset - cdStart;

    const eocd = new Uint8Array(22);
    const ev = new DataView(eocd.buffer);
    ev.setUint32(0, 0x06054b50, true);
    ev.setUint16(4, 0, true);
    ev.setUint16(6, 0, true);
    ev.setUint16(8, entries.length, true);
    ev.setUint16(10, entries.length, true);
    ev.setUint32(12, cdSize, true);
    ev.setUint32(16, cdStart, true);
    ev.setUint16(20, 0, true);

    const all = [concatUint8Arrays(localChunks)];
    // Rebuild properly: localChunks already contains headers+data in order, but we stored in array of separate chunks.
    const localBlob = concatUint8Arrays(localChunks);
    const centralBlob = concatUint8Arrays(centralChunks);
    return concatUint8Arrays([localBlob, centralBlob, eocd]);
  }

  function selectedQuestions(state) {
    const bank = state.bank || [];
    const byId = {};
    bank.forEach(function (question) { byId[question.id] = question; });
    return (state.exam.selectedIds || []).map(function (id) { return byId[id]; }).filter(Boolean);
  }

  function questionToOdt(question, index, options) {
    options = options || {};
    const lines = [];
    const cleanTitle = String(question.title || 'Pregunta')
      .replace(/^P\d+\s*·\s*/i, '')
      .replace(/^(Paso|Pasos)\s+[\d\s,y]+\s*:\s*/i, '')
      .replace(/^Punto de control del paso \d+:\s*/i, '')
      .trim();
    const titled = cleanTitle.charAt(0).toUpperCase() + cleanTitle.slice(1);
    lines.push('<text:h text:style-name="Heading" text:outline-level="2">' +
      '<text:span text:style-name="BoldLabel">' + escapeXml((index + 1) + '. ' + titled) + '</text:span>' +
      '</text:h>');
    if (question.text) {
      lines.push('<text:p text:style-name="Text_20_body">' + escapeXml(question.text) + '</text:p>');
    }
    if (question.type === 'multichoice') {
      const optionList = (question.options || []).filter(function (option) {
        return option && String(option.text || '').trim();
      });
      const isTeacher = !!(options && options.teacher);
      optionList.forEach(function (option, i) {
        const mark = (option.correct && isTeacher) ? '  (correcta)' : '';
        lines.push('<text:p text:style-name="List">' + escapeXml(String.fromCharCode(97 + i) + ') ' + option.text + mark) + '</text:p>');
      });
    } else if (question.type === 'truefalse') {
      lines.push('<text:p text:style-name="List">a) Verdadero</text:p>');
      lines.push('<text:p text:style-name="List">b) Falso</text:p>');
    } else if (question.type === 'matching') {
      (question.matchingPairs || []).forEach(function (pair) {
        if (pair.left || pair.right) {
          lines.push('<text:p text:style-name="List">' + escapeXml(pair.left + '  →  ' + pair.right) + '</text:p>');
        }
      });
    } else if (question.type === 'essay') {
      /* Sin huecos de respuesta */
    }
    if (options && options.teacher) {
      const fb = question.generalFeedback && String(question.generalFeedback).trim();
      if (fb) {
        lines.push('<text:p text:style-name="Text_20_body"><text:span text:style-name="BoldLabel">Retroalimentación:</text:span> ' + escapeXml(fb) + '</text:p>');
      }
      if (question.type === 'essay' && question.essay && question.essay.graderInfo) {
        lines.push('<text:p text:style-name="Text_20_body"><text:span text:style-name="BoldLabel">Criterios de corrección:</text:span> ' + escapeXml(question.essay.graderInfo) + '</text:p>');
      }
      if (question.type === 'multichoice' || question.type === 'truefalse' || question.type === 'shortanswer' || question.type === 'matching') {
        // include correct answer summary for teacher
        if (question.type === 'truefalse') {
          lines.push('<text:p text:style-name="Text_20_body"><text:span text:style-name="BoldLabel">Respuesta correcta:</text:span> ' + (question.trueAnswer === false ? 'Falso' : 'Verdadero') + '</text:p>');
        }
        if (question.type === 'shortanswer' && question.answers && question.answers.length) {
          lines.push('<text:p text:style-name="Text_20_body"><text:span text:style-name="BoldLabel">Respuestas aceptadas:</text:span> ' + escapeXml(question.answers.join(', ')) + '</text:p>');
        }
        if (question.type === 'matching' && question.matchingPairs && question.matchingPairs.length) {
          lines.push('<text:p text:style-name="Text_20_body"><text:span text:style-name="BoldLabel">Parejas correctas:</text:span></text:p>');
          question.matchingPairs.forEach(function (pair) {
            lines.push('<text:p text:style-name="List">' + escapeXml(pair.left + ' → ' + pair.right) + '</text:p>');
          });
        }
      }
    }
    lines.push('<text:p text:style-name="Text_20_body"></text:p>');
    return lines.join('\\n');
  }

  function buildContentXml(originalContentXml, state, options) {
    options = options || {};
    const questions = selectedQuestions(state);
    const exam = state.exam || {};

    const extraStyles =
      '<style:style style:name="BoldLabel" style:family="text"><style:text-properties fo:font-weight="bold"/></style:style>' +
      '<style:style style:name="SmallText" style:family="text"><style:text-properties fo:font-size="9pt"/></style:style>' +
      '<style:style style:name="BlockFirst" style:family="paragraph" style:parent-style-name="Text_20_body"><style:paragraph-properties fo:margin-top="0.5cm" fo:margin-bottom="0.0cm" fo:line-height="100%"/><style:text-properties fo:font-size="9pt"/></style:style>' +
      '<style:style style:name="BlockRA" style:family="paragraph" style:parent-style-name="Text_20_body"><style:paragraph-properties fo:margin-top="0.4cm" fo:margin-bottom="0.0cm" fo:line-height="100%"/><style:text-properties fo:font-size="9pt"/></style:style>' +
      '<style:style style:name="BlockCrit" style:family="paragraph" style:parent-style-name="Text_20_body"><style:paragraph-properties fo:margin-top="0.4cm" fo:margin-bottom="0.0cm" fo:line-height="100%"/><style:text-properties fo:font-size="9pt"/></style:style>' +
      '<style:style style:name="Spacer05" style:family="paragraph" style:parent-style-name="Text_20_body"><style:paragraph-properties fo:margin-top="0.5cm" fo:margin-bottom="0.0cm" fo:line-height="100%"/><style:text-properties fo:font-size="14pt"/></style:style>' +
      '<style:style style:name="Spacer04" style:family="paragraph" style:parent-style-name="Text_20_body"><style:paragraph-properties fo:margin-top="0.4cm" fo:margin-bottom="0.0cm" fo:line-height="100%"/><style:text-properties fo:font-size="11pt"/></style:style>' +
      '<style:style style:name="BlockRest" style:family="paragraph" style:parent-style-name="Text_20_body"><style:paragraph-properties fo:margin-top="0.0cm" fo:margin-bottom="0.0cm" fo:line-height="100%"/><style:text-properties fo:font-size="9pt"/></style:style>' +
      '<style:style style:name="Spacer" style:family="paragraph" style:parent-style-name="Text_20_body"><style:paragraph-properties fo:margin-top="0.5cm" fo:margin-bottom="0cm" fo:line-height="100%"/><style:text-properties fo:font-size="8pt"/></style:style>' +
      '<text:list-style style:name="CritList">' +
        '<text:list-level-style-number text:level="1" style:num-format="a" text:display-levels="1">' +
          '<style:list-level-properties text:list-level-position-and-space-mode="label-alignment">' +
            '<style:list-level-label-alignment text:label-followed-by="listtab" text:list-tab-stop-position="1.25cm"/>' +
          '</style:list-level-properties>' +
        '</text:list-level-style-number>' +
      '</text:list-style>';

    const styledXml = originalContentXml.replace('</office:automatic-styles>', extraStyles + '</office:automatic-styles>');

    const bodyParts = [];
    bodyParts.push('<office:body><office:text>');

    const selectedRas = Array.isArray(exam.selectedRas) ? exam.selectedRas : [];
    const summaryParts = [];
    if (exam.cycleName) summaryParts.push('Ciclo formativo: ' + exam.cycleName + '.');
    if (exam.moduleName || exam.moduleCode) {
      summaryParts.push('Módulo profesional: ' + (exam.moduleName || '') +
        (exam.moduleCode ? ' (' + exam.moduleCode + ')' : '') + '.');
    }
    if (selectedRas.length) {
      summaryParts.push('Resultados de aprendizaje que se trabajan: ' +
        selectedRas.map(function (item) {
          return item.raDisplay + (item.raText ? ': ' + item.raText : '');
        }).join(' ') + '.');
      const criteriaLines = [];
      selectedRas.forEach(function (item) {
        (item.criteriaDetails || []).forEach(function (criterion) {
          criteriaLines.push('CE ' + criterion.letter + ') ' + criterion.text);
        });
      });
      if (criteriaLines.length) {
        summaryParts.push('Criterios de evaluación: ' + criteriaLines.join('; ') + '.');
      }
    } else {
      if (exam.ra) summaryParts.push('Resultado de aprendizaje: ' + exam.ra +
        (exam.raText ? ': ' + exam.raText : '') + '.');
      if (exam.criteria && exam.criteria.length) {
        summaryParts.push('Criterios de evaluación: ' +
          exam.criteria.map(function (letter) { return 'CE ' + letter + ')'; }).join(', ') + '.');
      }
    }
    if (summaryParts.length) {
      // Bloque compacto: ciclo y módulo
      const block1 = [];
      if (exam.cycleName) block1.push('Ciclo formativo: ' + (exam.cycleName || ''));
      if (exam.moduleName || exam.moduleCode) {
        block1.push('Módulo profesional: ' + (exam.moduleName || '') + (exam.moduleCode ? ' (' + exam.moduleCode + ')' : ''));
      }
      if (block1.length) {
        bodyParts.push('<text:p text:style-name="BlockFirst">' +
          block1.map(function (line) {
            return '<text:span text:style-name="BoldLabel">' + escapeXml(line.split(':')[0] + ':') + '</text:span> ' + escapeXml(line.split(':').slice(1).join(':').trim());
          }).join('<text:line-break/>') +
          '</text:p>');
      }

      // Bloque RA con más espacio superior
      const raLines = [];
      if (selectedRas.length) {
        selectedRas.forEach(function (item) {
          raLines.push((item.raDisplay || 'RA' + item.raNumber) + ': ' + (item.raText || ''));
        });
      } else if (exam.ra) {
        raLines.push(exam.ra + (exam.raText ? ': ' + exam.raText : ''));
      }
      if (raLines.length) {
        bodyParts.push('<text:p text:style-name="BlockRA"><text:span text:style-name="BoldLabel">Resultados de aprendizaje que se trabajan:</text:span></text:p>');
        raLines.forEach(function (line) {
          bodyParts.push('<text:p text:style-name="BlockRest"><text:span text:style-name="SmallText">' + escapeXml(line) + '</text:span></text:p>');
        });
      }

      // Bloque criterios tal y como están
      const criteriaLines = [];
      if (selectedRas.length) {
        selectedRas.forEach(function (item) {
          (item.criteriaDetails || []).forEach(function (criterion) {
            criteriaLines.push((item.raDisplay || 'RA' + item.raNumber) + '·' + criterion.letter + ') ' + criterion.text);
          });
        });
      } else if (exam.criteria && exam.criteria.length) {
        exam.criteria.forEach(function (letter) {
          criteriaLines.push((exam.ra || 'RA') + '·' + letter + ')');
        });
      }
      if (criteriaLines.length) {
        bodyParts.push('<text:p text:style-name="BlockCrit"><text:span text:style-name="BoldLabel">Criterios de evaluación:</text:span></text:p>');
        criteriaLines.forEach(function (line) {
          bodyParts.push('<text:p text:style-name="BlockRest"><text:span text:style-name="SmallText">' + escapeXml(line) + '</text:span></text:p>');
        });
      }
    }
    bodyParts.push('<text:h text:style-name="Heading" text:outline-level="1">Consideraciones</text:h>');
    const considerationText = exam.description && String(exam.description).trim()
      ? exam.description
      : 'Lee atentamente cada pregunta y responde con claridad y orden.';
    bodyParts.push('<text:p text:style-name="Text_20_body">' + escapeXml(considerationText) + '</text:p>');
    bodyParts.push('<text:p text:style-name="Text_20_body">' +
      escapeXml('Por cada pregunta, en Moodle estará habilitado un espacio para escribir la respuesta a la pregunta y un hueco para subir una captura de pantalla con la actividad realizada.') +
      '</text:p>');
    bodyParts.push('<text:p text:style-name="Text_20_body"></text:p>');

    bodyParts.push('<text:h text:style-name="Heading" text:outline-level="1">Preguntas</text:h>');
    if (!questions.length) {
      bodyParts.push('<text:p text:style-name="Text_20_body">No hay preguntas seleccionadas.</text:p>');
    } else {
      questions.forEach(function (question, index) {
        bodyParts.push(questionToOdt(question, index, options));
      });
    }

    bodyParts.push('</office:text></office:body>');

    const newBody = bodyParts.join('\n');
    // Reemplazar el body original
    const replaced = styledXml.replace(/<office:body>[\s\S]*<\/office:body>/, newBody);
    if (replaced === styledXml) {
      // Fallback: insertar antes de </office:document-content>
      return styledXml.replace('</office:document-content>', newBody + '</office:document-content>');
    }
    return replaced;
  }

  function applyStylesPlaceholders(stylesXml, state) {
    const exam = state.exam || {};
    const source = state.source || {};

    const title = exam.title || '';
    const ra = exam.ra || (exam.raText ? exam.raText : '');
    const modulo = exam.moduleName || exam.course || (source.subject || '');
    const curso = exam.cycleName || (source.courseLevel || '');
    const unidad = source.unit || '';
    const departamento = source.school || 'DEPARTAMENTO';

    const letters = (exam.criteria && exam.criteria.length)
      ? exam.criteria
      : (source.criteria ? source.criteria.map(function (c) { return c.letter; }) : []);
    const criterios = letters.map(function (letter) { return 'CE ' + letter + ')'; }).join(', ');

    let result = stylesXml;

    // titulo_examen fragmentado
    result = result.replace(
      /<text:span text:style-name="MT1">\{\{<\/text:span><text:span text:style-name="MT2">titulo_examen\}<\/text:span><text:span text:style-name="MT1">\}<\/text:span>/g,
      escapeXml(title)
    );

    result = result.replace(/\{\{RA\}\}/g, escapeXml(ra));
    result = result.replace(/\{\{criterios_evaluación\}\}/g, escapeXml(criterios));
    result = result.replace(/\{\{MODULO\}\}/g, escapeXml(modulo));
    result = result.replace(/\{\{CURSO\}\} \{\{UNIDAD\}\}/g, escapeXml((curso + ' ' + unidad).trim()));
    result = result.replace(/\{\{CURSO\}\}/g, escapeXml(curso));
    result = result.replace(/\{\{UNIDAD\}\}/g, escapeXml(unidad));

    // DEPARTAMENTO fragmentado
    result = result.replace(
      /\{\{<text:span text:style-name="MT5">DEPARTAMENTO<\/text:span>\}\}/g,
      escapeXml(departamento)
    );

    return result;
  }

  async function fillAndDownload(state, options) {
    options = options || {};
    if (!state || !(state.exam && state.exam.selectedIds && state.exam.selectedIds.length)) {
      throw new Error('No hay preguntas seleccionadas.');
    }

    const binary = atob(TEMPLATE_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
    const buffer = bytes.buffer;

    const entries = await readZip(buffer);

    const newEntries = entries.map(function (entry) {
      if (entry.name === 'styles.xml') {
        const text = new TextDecoder('utf-8').decode(entry.data);
        const replaced = applyStylesPlaceholders(text, state);
        return { name: entry.name, data: new TextEncoder().encode(replaced) };
      }
      if (entry.name === 'content.xml') {
        const text = new TextDecoder('utf-8').decode(entry.data);
        const replaced = buildContentXml(text, state, options);
        return { name: entry.name, data: new TextEncoder().encode(replaced) };
      }
      return { name: entry.name, data: entry.data };
    });

    const zipBytes = writeZip(newEntries);
    const blob = new Blob([zipBytes], { type: 'application/vnd.oasis.opendocument.text' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    const baseName = (Util.slug(state.exam.fileName || state.exam.title, 'examen') || 'examen');
    const suffix = options.teacher ? '-correccion' : '';
    const name = baseName + suffix + '.odt';
    link.download = name;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  }

  ExamBuilder.Odt = {
    fillAndDownload: fillAndDownload,
  };
})(typeof window !== 'undefined' ? window : globalThis);